=== std/bash ===
std/bash:
flake.lock
flake.nix
worker

--- std/bash/flake.lock
{
  "nodes": {
    "nixpkgs": {
      "locked": {
        "lastModified": 1781577229,
        "narHash": "sha256-lrp67w8AulE9Ks53n27I45ADSzbOCn4H+CNW1Ck8B+8=",
        "owner": "NixOS",
        "repo": "nixpkgs",
        "rev": "567a49d1913ce81ac6e9582e3553dd90a955875f",
        "type": "github"
      },
      "original": {
        "owner": "NixOS",
        "ref": "nixos-unstable",
        "repo": "nixpkgs",
        "type": "github"
      }
    },
    "root": {
      "inputs": {
        "nixpkgs": "nixpkgs"
      }
    }
  },
  "root": "root",
  "version": 7
}
--- std/bash/flake.nix
{
  # std/bash (design/flake-images.md): the script worker — a complete
  # interpreter worker image. /worker is the script runner (./worker,
  # checked in right here): it fetches the `worker1` arg — the script, the
  # next executable in the chain — and runs it with bash. The contents are
  # the shell and file tools a worker script leans on. Curry a script on
  # (`--worker1:@=…`) and run it like any image.
  #
  # The contract (std/flake-builder/worker): a flake defines everything about
  # the image except the caos additions. /worker included.
  #
  # This directory IS the published tree (literal trees, part 2): flake.nix,
  # flake.lock (derived from the main flake.lock by std/refresh.sh), worker
  # — build-builtins.sh copies it whole, and tests/std-lint verifies the
  # checked-in redundancies.
  description = "caos std/bash — the script worker: shell + file tools, /worker runs `worker1`";

  inputs.nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";

  outputs =
    { self, nixpkgs }:
    let
      forSystem =
        system:
        let
          pkgs = import nixpkgs { inherit system; };
          workerRoot = pkgs.runCommand "bash-worker-root" { } ''
            mkdir -p $out
            install -m 755 ${./worker} $out/worker
          '';
        in
        pkgs.dockerTools.buildLayeredImage {
          name = "bash";
          tag = "latest";
          # bash provides /bin/sh too. No Entrypoint: runnerd forces
          # `/bin/caos runner`, which execs /worker.
          contents = [
            workerRoot
            pkgs.bash
            pkgs.coreutils
            pkgs.diffutils
            pkgs.gnugrep
            pkgs.findutils
            # JSON plumbing for worker scripts — std/refresh.sh's lock
            # derivation (the std-lint suite check) among them.
            pkgs.jq
          ];
          config = {
            Env = [ "PATH=/bin" ];
          };
        };
    in
    {
      packages = builtins.listToAttrs (
        map
          (system: {
            name = system;
            value = {
              caosImage = forSystem system;
            };
          })
          [
            "x86_64-linux"
            "aarch64-linux"
          ]
      );
    };
}
--- std/bash/worker
#!/usr/bin/env bash
# std/bash/worker is this script's only copy; the suite's image jobs
# (caos-tools/build.sh) read it here.
# (env shebang: the flake image this defines (std/bash) has
# bash at /bin/bash, but the nix-builder images have only the nix profile's —
# /usr/bin/env, which the flake-builder's caos delta guarantees, is the
# portable meeting point.)
# The caos runner runs us as /worker, with /cas set up and the args
# materialized under /cas/args. We are a script interpreter: fetch the next
# executable in the chain (`worker1` — the workerN naming for anything that
# gets fetched and run) and run it with bash; on exit caos reads the hash of
# /cas/out. If the script left no result there, store an empty blob so
# there's something to read.
set -euo pipefail
caos get /cas/args/worker1
bash /cas/args/worker1
if [ ! -e /cas/out ]; then
  : > /tmp/caos-empty-out
  caos put /tmp/caos-empty-out /cas/out
fi

